fn main(){let args:Vec<_>=std::env::args().skip(1).collect();if args==["--check-minimal-environment"]{if std::env::var_os("PATH").is_some()||std::env::var_os("SystemRoot").is_none()||std::env::var_os("TEMP").is_none()||std::env::var_os("TEMP").map(std::path::PathBuf::from)==std::env::current_dir().ok(){std::process::exit(3)}return;}if args==["--grandchild"]{let _child=std::process::Command::new(std::env::current_exe().unwrap()).arg("--sleep").spawn().unwrap();}else if args!=["--sleep"]{std::process::exit(2)}std::thread::sleep(std::time::Duration::from_secs(30));}
